<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import type {EChartsOption} from 'echarts'
import PageHeader from '@/components/PageHeader.vue';import LoadingState from '@/components/LoadingState.vue';import EmptyState from '@/components/EmptyState.vue';import ErrorState from '@/components/ErrorState.vue';import BaseChart from '@/components/BaseChart.vue';import StatusTag from '@/components/StatusTag.vue'
import {useSiteStore} from '@/stores/site';import {systemApi} from '@/api/system';import {dataSourcesApi} from '@/api/dataSources';import {simulationApi} from '@/api/simulation'
import type {DataSourceStatus,SystemOverview,SystemTaskSummary,SystemTraceability} from '@/types'
const FRONTEND_VERSION='V1.0.0-beta.15',siteStore=useSiteStore(),loading=ref(true),busyId=ref<number|null>(null),error=ref<string|null>(null),operationMessage=ref<string|null>(null),overview=ref<SystemOverview|null>(null),sources=ref<DataSourceStatus[]>([]),tasks=ref<SystemTaskSummary[]>([]),trace=ref<SystemTraceability|null>(null),models=ref<string[]>([]),traceVersion=ref<number|null>(null),traceSource=ref<number|null>(null),activeTab=ref('overview');const health=computed(()=>overview.value?.health);const pct=(v:number|null)=>v==null?'暂无数据':`${(v*100).toFixed(1)}%`;const time=(v:string|null)=>v?new Date(v).toLocaleString('zh-CN'):'暂无数据'
const sourceStatusOption=computed<EChartsOption>(()=>{const counts:Record<string,number>={};for(const x of sources.value)counts[x.status]=(counts[x.status]||0)+1;return{series:[{name:'数据源状态',type:'pie',radius:['40%','70%'],data:Object.entries(counts).map(([name,value])=>({name,value}))}]}});const taskStatusOption=computed<EChartsOption>(()=>{const counts:Record<string,number>={};for(const x of tasks.value)counts[x.status]=(counts[x.status]||0)+1;return{xAxis:{type:'category',data:Object.keys(counts)},yAxis:{type:'value',minInterval:1},series:[{name:'任务状态',type:'bar',data:Object.values(counts)}]}});const qualityOption=computed<EChartsOption>(()=>({xAxis:{type:'category',axisLabel:{rotate:20},data:sources.value.map(x=>x.name)},yAxis:{type:'value',max:1,axisLabel:{formatter:(v:number)=>`${v*100}%`}},series:[{name:'数据质量',type:'bar',data:sources.value.map(x=>x.quality_rate)}]}))
async function initialize(){loading.value=true;error.value=null;try{await siteStore.loadSites();[overview.value,sources.value,tasks.value]=await Promise.all([systemApi.overview(),systemApi.dataSources(),systemApi.tasks()]);const registry=await simulationApi.models();models.value=[...new Set([...(registry.models||[]),...(registry.measure_types||[])])]}catch(e){error.value=(e as {message?:string}).message||'系统状态加载失败'}finally{loading.value=false}}
async function testSource(id:number){busyId.value=id;operationMessage.value=null;try{const result=await dataSourcesApi.test(id);operationMessage.value=`连接测试：${result.success?'成功':'失败'} · ${result.message}`}catch(e){operationMessage.value=(e as {message?:string}).message||'连接测试失败'}finally{busyId.value=null}}
async function syncSource(id:number){busyId.value=id;operationMessage.value=null;try{const r=await dataSourcesApi.sync(id);operationMessage.value=`同步完成：写入 ${r.inserted}，拒绝 ${r.quarantined}，警告 ${r.warnings}`;await initialize()}catch(e){operationMessage.value=(e as {message?:string}).message||'同步失败'}finally{busyId.value=null}}
async function loadTrace(){if(!traceVersion.value&&!traceSource.value){operationMessage.value='请输入 ScenarioVersion ID 或选择 DataSource';return}try{trace.value=await systemApi.trace({scenario_version_id:traceVersion.value||undefined,data_source_id:traceSource.value||undefined})}catch(e){operationMessage.value=(e as {message?:string}).message||'追溯查询失败'}}
onMounted(initialize)
</script>
<template><section><PageHeader kicker="SYSTEM OPERATIONS" title="系统管理与运行保障" description="集中观察系统、数据接入、Provider、任务和业务追溯状态；所有结论均来自实时只读查询。"><el-button :loading="loading" @click="initialize">刷新状态</el-button></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="initialize"/><template v-else-if="overview"><section class="system-overview"><article><span>前端版本</span><b>{{FRONTEND_VERSION}}</b></article><article><span>后端 / API</span><b>{{health?.backend_version}} / {{health?.api_version}}</b></article><article><span>数据库 Revision</span><b>{{health?.alembic_revision||'未检测到'}} <StatusTag :status="health?.is_head?'HEAD':'NOT_HEAD'"/></b></article><article><span>后端健康</span><b><StatusTag :status="health?.application_status||'UNKNOWN'"/> {{health?.database_status==='UP'?'数据库已连接':'数据库连接失败'}}</b></article><article><span>数据源</span><b>{{overview.data_source_count}} · 正常 {{overview.normal_data_source_count}} / 异常 {{overview.abnormal_data_source_count}}</b></article><article><span>Provider</span><b>动态 {{overview.providers.filter(x=>x.dynamic_data_available).length}} / fallback {{overview.providers.filter(x=>x.using_fallback).length}}</b></article><article><span>最近异常</span><b>{{time(overview.latest_system_exception_time)}}</b></article></section><el-alert v-if="operationMessage" :title="operationMessage" type="info" show-icon closable @close="operationMessage=null"/><el-tabs v-model="activeTab" class="system-tabs"><el-tab-pane label="系统概览" name="overview"><section class="chart-grid"><article class="panel"><h2>数据源状态分布</h2><BaseChart :option="sourceStatusOption" :empty="!sources.length"/></article><article class="panel"><h2>最近任务状态分布</h2><BaseChart :option="taskStatusOption" :empty="!tasks.length"/></article><article class="panel"><h2>数据质量分布</h2><BaseChart :option="qualityOption" :empty="!sources.length"/></article><article class="panel alerts"><h2>运行提醒</h2><EmptyState v-if="!overview.alerts.length" title="当前查询未发现运行提醒" description="这表示本次查询没有发现异常，不代表持续监控结论"/><div v-for="a in overview.alerts" :key="`${a.category}-${a.message}`"><StatusTag :status="a.level"/><b>{{a.category}}</b><span>{{a.message}}</span><small>{{time(a.occurred_at)}}</small></div></article></section></el-tab-pane>
<el-tab-pane label="数据源" name="sources"><article class="panel"><el-table :data="sources"><el-table-column prop="name" label="名称"/><el-table-column prop="source_type" label="类型"/><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="最近同步"><template #default="{row}">{{time(row.last_sync_at)}}</template></el-table-column><el-table-column label="最近成功"><template #default="{row}">{{time(row.last_success_at)}}</template></el-table-column><el-table-column label="最近失败"><template #default="{row}">{{time(row.last_failure_at)}}<small class="block">{{row.last_failure_reason||'无失败摘要'}}</small></template></el-table-column><el-table-column label="质量"><template #default="{row}">{{pct(row.quality_rate)}} · 有效 {{row.valid_records}} / 拒绝 {{row.rejected_records}} / 警告 {{row.warning_records}}</template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button v-if="row.supports_connection_test" link :loading="busyId===row.id" @click="testSource(row.id)">测试连接</el-button><el-button v-if="row.supports_manual_sync" link :loading="busyId===row.id" @click="syncSource(row.id)">手动同步</el-button></template></el-table-column></el-table><EmptyState v-if="!sources.length" title="暂无数据源"/></article></el-tab-pane>
<el-tab-pane label="Provider" name="providers"><section class="provider-grid"><article v-for="p in overview.providers" :key="p.provider" class="panel"><header><h2>{{p.provider}}</h2><el-tag :type="p.dynamic_data_available?'success':'warning'">{{p.dynamic_data_available?'动态数据可用':'当前使用 fallback'}}</el-tag></header><dl><dt>记录数</dt><dd>{{p.record_count}}</dd><dt>最新时间</dt><dd>{{time(p.latest_data_time)}}</dd><dt>数据范围</dt><dd>{{time(p.range_start)}} — {{time(p.range_end)}}</dd><dt>来源</dt><dd>{{p.source||'暂无来源记录'}}</dd></dl></article></section></el-tab-pane>
<el-tab-pane label="模型能力" name="models"><article class="panel"><h2>小时仿真模型注册状态</h2><div class="model-cloud"><el-tag v-for="m in models" :key="m" size="large">{{m}}</el-tag></div><p>接口要求的七类能力：{{overview.models.join('、')}}</p></article></el-tab-pane>
<el-tab-pane label="运行任务" name="tasks"><article class="panel"><el-table :data="tasks"><el-table-column prop="task_type" label="类型"/><el-table-column prop="id" label="ID"/><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="创建时间"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column label="完成时间"><template #default="{row}">{{time(row.finished_at)}}</template></el-table-column><el-table-column prop="failure_reason" label="失败原因"><template #default="{row}">{{row.failure_reason||'—'}}</template></el-table-column></el-table><EmptyState v-if="!tasks.length" title="暂无运行任务"/></article></el-tab-pane>
<el-tab-pane label="配置与版本" name="config"><div class="config-grid"><article class="panel"><h2>数据库与版本</h2><dl><dt>数据库类型</dt><dd>{{health?.database_type}}</dd><dt>当前 Revision</dt><dd>{{health?.alembic_revision||'未检测到'}}</dd><dt>目标 Head</dt><dd>{{health?.alembic_head}}</dd><dt>是否 Head</dt><dd>{{health?.is_head?'是':'否'}}</dd><dt>后端版本</dt><dd>{{health?.backend_version}}</dd><dt>API 版本</dt><dd>{{health?.api_version}}</dd><dt>服务时间</dt><dd>{{time(health?.current_time||null)}}</dd><dt>Uptime</dt><dd>{{health?.uptime_seconds==null?'未启用采集':`${health.uptime_seconds}s`}}</dd></dl></article><article class="panel"><h2>非敏感配置</h2><dl><dt>默认时区</dt><dd>{{overview.configuration.default_timezone}}</dd><dt>排放因子模式</dt><dd>{{overview.configuration.default_emission_factor_mode}}</dd><dt>电价模式</dt><dd>{{overview.configuration.default_electricity_price_mode}}</dd><dt>文件存储</dt><dd>{{overview.configuration.file_storage_type}}</dd><dt>API Base</dt><dd>{{overview.configuration.api_base_configuration}}</dd></dl><el-alert title="密码、token、secret、数据库连接串和私钥不会由系统状态 API 返回。" type="info" :closable="false"/></article></div></el-tab-pane>
<el-tab-pane label="审计追溯" name="trace"><article class="panel trace-controls"><el-input-number v-model="traceVersion" placeholder="ScenarioVersion ID"/><el-select v-model="traceSource" clearable placeholder="DataSource"><el-option v-for="s in sources" :key="s.id" :value="s.id" :label="`${s.name} #${s.id}`"/></el-select><el-button type="primary" @click="loadTrace">查询只读链路</el-button></article><article v-if="trace" class="panel"><h2>业务追溯视图</h2><EmptyState v-if="!trace.nodes.length" title="未找到追溯节点"/><div class="trace-nodes"><div v-for="node in trace.nodes" :key="node.key"><span>{{node.type}}</span><b>{{node.label}}</b><StatusTag v-if="node.status" :status="node.status"/></div></div><h3>关系</h3><div class="trace-edges"><code v-for="edge in trace.edges" :key="`${edge.from}-${edge.to}`">{{edge.from}} → {{edge.to}}</code></div></article><EmptyState v-else title="请选择追溯入口" description="支持 ScenarioVersion 业务链和 DataSource 数据链"/></el-tab-pane></el-tabs></template></section></template>
